import{_ as e,c as a,a2 as i,o}from"./chunks/framework.CO0qOYmW.js";const p=JSON.parse('{"title":"设计理念","description":"","frontmatter":{"title":"设计理念","category":"前端 · Vue 2","tags":["Vue"],"excerpt":"Vuejs是一套用于构建用户界面的 渐进式 JavaScript 框架。 Vuejs 被设计为可以自底向上、逐层应用。 Vue2 是Vuejs的第二个版本。 Vue 的核心库只关注视图层 易于上手，也便于与第三方库或既有项目整合 可以根据项..."},"headers":[],"relativePath":"frontend/06-vue2/01-01-introduction.md","filePath":"frontend/06-vue2/01-01-introduction.md","lastUpdated":1773591891000}'),t={name:"frontend/06-vue2/01-01-introduction.md"};function s(c,l,d,u,r,n){return o(),a("div",null,l[0]||(l[0]=[i(`<h1 id="设计理念" tabindex="-1">设计理念 <a class="header-anchor" href="#设计理念" aria-label="Permalink to &quot;设计理念&quot;">​</a></h1><h2 id="一、-vue-2-是什么" tabindex="-1">一、 Vue 2 是什么 <a class="header-anchor" href="#一、-vue-2-是什么" aria-label="Permalink to &quot;一、 Vue 2 是什么&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Vue 2 定义</p><ol><li><code>Vuejs</code>是一套用于构建用户界面的 <strong>渐进式 JavaScript 框架</strong>。</li><li><code>Vuejs</code> 被设计为可以自底向上、逐层应用。</li><li><code>Vue2</code> 是<code>Vuejs</code>的第二个版本。</li></ol></div><h2 id="二、核心特性" tabindex="-1">二、核心特性 <a class="header-anchor" href="#二、核心特性" aria-label="Permalink to &quot;二、核心特性&quot;">​</a></h2><h3 id="_2-1-渐进式框架" tabindex="-1">2.1 渐进式框架 <a class="header-anchor" href="#_2-1-渐进式框架" aria-label="Permalink to &quot;2.1 渐进式框架&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">渐进式</p><ul><li>Vue 的核心库只关注视图层</li><li>易于上手，也便于与第三方库或既有项目整合</li><li>可以根据项目需求逐步采用 Vue 的功能</li></ul></div><h3 id="_2-2-响应式" tabindex="-1">2.2 响应式 <a class="header-anchor" href="#_2-2-响应式" aria-label="Permalink to &quot;2.2 响应式&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">响应式系统</p><ul><li>基于 <code>Object.defineProperty</code> 实现响应式系统</li><li>数据变化时自动更新视图</li><li>支持双向数据绑定（<code>v-model</code>）</li></ul></div><h3 id="_2-3-组件化开发" tabindex="-1">2.3 组件化开发 <a class="header-anchor" href="#_2-3-组件化开发" aria-label="Permalink to &quot;2.3 组件化开发&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">组件化</p><ul><li>将页面拆分为可复用的组件</li><li>组件可以嵌套、组合</li><li>支持单文件组件（<code>.vue</code>）</li></ul></div><h3 id="_2-4-虚拟-dom" tabindex="-1">2.4 虚拟 DOM <a class="header-anchor" href="#_2-4-虚拟-dom" aria-label="Permalink to &quot;2.4 虚拟 DOM&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">虚拟 DOM</p><ul><li>使用虚拟 DOM 提高渲染性能</li><li>通过 diff 算法最小化 DOM 操作</li><li>支持服务端渲染（<code>SSR</code>）</li></ul></div><h2 id="三、设计理念" tabindex="-1">三、设计理念 <a class="header-anchor" href="#三、设计理念" aria-label="Permalink to &quot;三、设计理念&quot;">​</a></h2><h3 id="_3-1-易用性" tabindex="-1">3.1 易用性 <a class="header-anchor" href="#_3-1-易用性" aria-label="Permalink to &quot;3.1 易用性&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">易用性</p><ul><li>学习曲线平缓</li><li>API 设计直观</li><li>文档完善</li></ul></div><h3 id="_3-2-灵活性" tabindex="-1">3.2 灵活性 <a class="header-anchor" href="#_3-2-灵活性" aria-label="Permalink to &quot;3.2 灵活性&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">灵活性</p><ul><li>可以逐步采用</li><li>不强制特定的项目结构</li><li>支持多种开发方式</li></ul></div><h3 id="_3-3-高效性" tabindex="-1">3.3 高效性 <a class="header-anchor" href="#_3-3-高效性" aria-label="Permalink to &quot;3.3 高效性&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">高效性</p><ul><li>体积小（运行时约 34KB）</li><li>性能优秀</li><li>支持按需加载</li></ul></div><h2 id="四、mvvm-模式" tabindex="-1">四、MVVM 模式 <a class="header-anchor" href="#四、mvvm-模式" aria-label="Permalink to &quot;四、MVVM 模式&quot;">​</a></h2><p>Vue 2 采用 <strong>MVVM（Model-View-ViewModel）</strong> 架构模式：</p><details class="details custom-block"><summary>示意图</summary><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────┐         ┌──────────────┐         ┌─────────┐</span></span>
<span class="line"><span>│  Model  │ ◄─────► │ ViewModel    │ ◄─────► │  View   │</span></span>
<span class="line"><span>│  (数据) │         │  (Vue实例)   │         │  (模板) │</span></span>
<span class="line"><span>└─────────┘         └──────────────┘         └─────────┘</span></span></code></pre></div></details><div class="tip custom-block"><p class="custom-block-title">MVVM 模式</p><ul><li><code>Model（模型）</code>：数据层，存储应用的数据</li><li><code>View（视图）</code>：展示层，用户看到的界面</li><li><code>ViewModel（视图模型）</code>：连接层，Vue 实例，负责数据绑定和视图更新</li></ul></div><h2 id="五、适用场景" tabindex="-1">五、适用场景 <a class="header-anchor" href="#五、适用场景" aria-label="Permalink to &quot;五、适用场景&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">适用场景</p><ul><li>单页应用（<code>SPA</code>）</li><li>移动端 <code>H5</code> 应用</li><li>后台管理系统</li><li>中小型项目快速开发</li></ul></div><h2 id="六、生态系统" tabindex="-1">六、生态系统 <a class="header-anchor" href="#六、生态系统" aria-label="Permalink to &quot;六、生态系统&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Vue 2 生态系统</p><ul><li><code>Vue Router</code>：官方路由管理器</li><li><code>Vuex</code>：官方状态管理库</li><li><code>Vue CLI</code>：官方脚手架工具</li><li><code>Vue DevTools</code>：浏览器调试工具</li><li><code>Vue(official)</code>:语法高亮插件</li></ul></div>`,27)]))}const m=e(t,[["render",s]]);export{p as __pageData,m as default};
